function modularPKW(input:Inputs):CalculationResult {
  const data=calculateChargingNetwork(input), count=data.grids.reduce((sum,grid)=>sum+grid.stations.length,0), limited=data.assignedKW<data.installedKW-1e-8;
  return {
    metrics:[{label:"Ladebudget Haus · AC",value:data.availableACKW,unit:"kW"},{label:"Installierte Punktleistung",value:data.installedKW,unit:"kW"},{label:"Abgegebene Punktleistung",value:data.assignedKW,unit:"kW"},{label:"Ladepunkte",value:count,digits:0},{label:"Aktiv / wartend",value:`${data.activeCount} / ${data.waitingCount}`},{label:"Stärkster Haus-Aussenleiter",value:data.strongestPhaseCurrent,unit:"A"}],
    status:{tone:data.overload?"error":limited||data.waitingCount?"warning":"neutral",text:data.overload?"Haus-, Grid- oder Phasenbudget überschritten; ohne Lastmanagement bleibt der volle Bedarf sichtbar.":data.waitingCount?"Einzelne Ladepunkte warten, damit die eingegebenen Mindestleistungen und Phasenbudgets eingehalten werden.":limited?"Lastmanagement begrenzt die Punktleistung innerhalb der Haus-, Grid- und Phasenbudgets.":"Punktleistungen liegen innerhalb der modellierten Haus-, Grid- und Phasenbudgets."},
    rows:[{label:"AC-Aufnahme aller Ladepunkte",value:data.acInputKW,unit:"kW"},{label:"Haus L1 / L2 / L3 inkl. Gebäudereserve",value:data.housePhases.map(current=>fmt(current,2)).join(" / "),unit:"A"},...data.grids.map(grid=>({label:`${grid.label} · ${grid.activeCount} aktiv / ${grid.waitingCount} wartend`,value:`${fmt(grid.assignedKW)} kW Punktleistung · ${fmt(grid.acInputKW)} kW AC · L1/L2/L3 ${grid.phases.map(current=>fmt(current,2)).join(" / ")} A`}))],
    chargingNetwork:data,
    formula:`AC 1~: I = P × 1000 / 230 V; AC 3~: I = P × 1000 / (√3 × 400 V); DC: P_AC = P_DC / η. P_Haus = ${data.houseAmps} × √3 × 400 / 1000 = ${fmt(data.houseKW)} kW; Ladebudget = max(0, ${fmt(data.houseKW)} − ${fmt(data.reserveKW)}) = ${fmt(data.availableACKW)} kW AC. AC-Aufnahme = ΣP_AC,LP = ${fmt(data.acInputKW)} kW; abgegebene Punktleistung = ${fmt(data.assignedKW)} kW; stärkster Haus-Aussenleiter = max(${data.housePhases.map(current=>fmt(current,2)).join(", ")}) = ${fmt(data.strongestPhaseCurrent,2)} A.`,
    limitations:[data.factorBasis,data.minimumBasis,"Die gemischte Zuteilung ist eine eigene Budgetrechnung mit expliziter Aktivierungsreihenfolge, keine bestätigte Gleichwertigkeit jeder geschützten Referenzkonfiguration. PV/Speicher sind in diesem Mehrgrid-Modell nicht enthalten. Schutzgeräte, Kabel, Blindleistung, Oberwellen und Netzfreigabe werden nicht dimensioniert."]
  };
}

