function contractCosts(input:Inputs):CalculationResult {
  const data=calculateChargingCosts(input),selected=data.selected;
  return{metrics:[{label:`${selected.id} · Gesamtkosten ${data.years} Jahre`,value:selected.total,unit:"CHF",digits:0},{label:"Investition inkl. Ersatz",value:selected.capex,unit:"CHF",digits:0},{label:"Betrieb im Zeitraum",value:selected.opex,unit:"CHF",digits:0},{label:"Je Ladepunkt im Endausbau/Jahr",value:selected.averagePerPointYear,unit:"CHF/a",digits:0}],
    status:{tone:"neutral",text:`${selected.label}: nominaler Kostenvergleich aus den eingegebenen Preisen und Gebühren. Kein automatischer Tarif- oder Vertragsnachweis.`},
    rows:[{label:"Gesamt Ladepunkte",value:data.points},{label:"11-kW-Leistungsäquivalente",value:data.equivalent},{label:"Ladeenergie pro Jahr bei Endausbau",value:data.annualEnergy,unit:"kWh/a"},{label:"Gewichteter Strompreis",value:data.weightedTariff,unit:"CHF/kWh"},{label:"Energiekosten pro Jahr",value:data.energyCost,unit:"CHF/a"},{label:"Separate Wartung pro Jahr bei Endausbau",value:data.maintenanceAnnual,unit:"CHF/a"},{label:"Basisinfrastruktur",value:data.basis,unit:"CHF"},{label:"Stationen inkl. Installation",value:data.station,unit:"CHF"},...data.models.map(model=>({label:model.label,value:`${fmt(model.capex,0)} CHF Investition + ${fmt(model.opex,0)} CHF Betrieb = ${fmt(model.total,0)} CHF`}))],
    costModels:data.models,series:selected.series,seriesLabel:`${selected.id} · tatsächliche jährliche Zahlungen`,seriesUnit:"CHF",seriesLabels:["Investition / Ersatz","Betrieb inkl. Energie"],
    formula:`N_11kW = Σ(Anzahl × Leistung / 11) = ${fmt(data.equivalent,3)}; Energie/a bei Endausbau = Σ(Anzahl × Jahresenergie) = ${fmt(data.annualEnergy)} kWh; Stromkosten/a = ${fmt(data.annualEnergy)} × ${fmt(data.weightedTariff,3)} = ${fmt(data.energyCost)} CHF. ${selected.id}: Kosten = Investition inkl. Ersatz + Σ Betrieb je Jahr = ${fmt(selected.capex)} + ${fmt(selected.opex)} = ${fmt(selected.total)} CHF; je LP und Jahr = ${fmt(selected.total)} / ${data.points} / ${data.years} = ${fmt(selected.averagePerPointYear)} CHF/a.`,
    limitations:["Beobachtete Modellstruktur: V1 eigenes Eigentum/Betrieb, V2 eigenes Eigentum/Betriebscontracting, V3 eigene Basis/Stationscontracting, V4 vollständiges Contracting. Gebühren sind editierbare Projektwerte. Der beobachtete Basic-Fall mit vier AC-Punkten stimmt für alle vier Modellgesamtkosten und die V1-Jahreszahlungen überein. DC-Klassen und Detailmodus sind damit nicht vollständig gegen die geschützte Referenz validiert.","Separate Wartung wird als Jahresbetrag nur für V1 gerechnet; V2–V4 enthalten den Betrieb in ihren Contractinggebühren. Vertragsumfang am konkreten Angebot prüfen. Ersatz nach dem gewählten Zyklus betrifft V1/V2. Inbetriebnahmen werden je Kostenposition im Betriebsjahr erfasst; Gebühren und Energie fallen erst ab diesem Jahr an. Ersatz folgt dem jeweiligen Kohortenalter. Die Säulen zeigen Zahlungen, keine zusätzliche Abschreibung.","Detailkosten bilden explizite manuelle Netz-/Trassen-/Projektierungsannahmen ab; keine automatisch bestätigten Netzbetreibertarife. MWST, Inflation, Finanzierung, Steuern und Restwerte sind nicht berücksichtigt."]};
}

